@@ -0,0 +1,25 @@
+// API keys and roles. A viewer may only read, a cook may also do the kitchen's
+// daily work (COOK_ROUTES), a manager may do everything. A route listed nowhere
+// is therefore readable if it is a GET and manager-only otherwise.
+import { createHash, timingSafeEqual } from "node:crypto";
+
+const MANAGER_ONLY_READS = new Set(["GET /audit"]);
+const COOK_ROUTES = new Set(["POST /recipes/:id/cook", "POST /batches/:id/waste", "POST /temperatures", "POST /stocktakes/:id/counts"]);
+
+const digest = (text) => createHash("sha256").update(text).digest();
+
+/** The API key record for a presented key, or null if it is unknown. */
+export function findKey(store, presented) {
+  if (!presented) return null;
+  const wanted = digest(presented);
+  return store.data.apiKeys.find((k) => timingSafeEqual(digest(k.key), wanted)) ?? null;
+}
+
+/** Whether `role` may call the route `method pattern`; an unknown role may not. */
+export function canAccess(role, method, pattern) {
+  const route = `${method} ${pattern}`;
+  if (role === "manager") return true;
+  if (role !== "viewer" && role !== "cook") return false;
+  if (method === "GET") return !MANAGER_ONLY_READS.has(route);
+  return role === "cook" && COOK_ROUTES.has(route);
+}
