@@ -0,0 +1,14 @@
+// The audit log: one entry per request that changed data. Entries are never
+// edited or deleted (docs/DATA.md).
+
+/** Appends an audit entry and returns it. */
+export function recordAudit(store, { at, keyName, method, path, status }) {
+  const entry = { id: store.nextId("audit"), at, keyName, method, path, status };
+  store.data.audit.push(entry);
+  return entry;
+}
+
+/** Audit entries, newest first. */
+export function listAudit(store) {
+  return [...store.data.audit].reverse();
+}
